#include "text_model.h"
#include <future>
#include <iostream>
#include <thread>
#include <iomanip>
#include <sstream>

std::string quote(const std::string& text) {
 std::ostringstream out; out << '"';
 for(unsigned char c:text) { if(c=='"'||c=='\\') out << '\\' << c; else if(c=='\n') out << "\\n"; else if(c=='\r') out << "\\r"; else if(c<32) out << "\\u" << std::hex << std::setw(4) << std::setfill('0') << int(c) << std::dec; else out << c; }
 out << '"'; return out.str();
}
int main(int argc,char** argv) {
 if(argc!=2) return 2;
 try {
  transiber::TextModel model(argv[1],2,0,3);
  const std::string instruction="You are an expert at translating text from English to Arabic.\n\n";
  int failures=0;
  const auto reject=[&](const char* name,const std::string& prompt,const char* expected) {
   std::string error;bool published=false;
   try { const auto text=model.translate(prompt);published=!text.empty(); }
   catch(const std::exception& e) { error=e.what(); }
   bool pass=!published&&error.find(expected)!=std::string::npos;
   std::cout << "{\"case\":" << quote(name) << ",\"accepted\":" << (pass?"true":"false") << ",\"publishedText\":" << (published?"true":"false") << ",\"error\":" << quote(error) << "}" << std::endl;
   if(!pass) ++failures;
  };
  reject("missing-instruction","The meeting starts at nine.","instruction is missing");
  reject("oversized-input",instruction+std::string(12001,'a'),"exceeds 12000");
  std::string context;for(int i=0;i<1800;++i) context+="hello ";
  reject("context-overflow",instruction+context,"2048 tokens");
  const auto begin=std::chrono::steady_clock::now();
  auto task=std::async(std::launch::async,[&] {
   try { return std::pair<bool,std::string>{true,model.translate(instruction+"The meeting starts at nine in the morning, and everybody should bring the documents from the previous discussion. Please translate the entire message faithfully.")}; }
   catch(const std::exception& e) { return std::pair<bool,std::string>{false,e.what()}; }
  });
  std::this_thread::sleep_for(std::chrono::milliseconds(75));
  const bool pendingAtCancel=task.wait_for(std::chrono::milliseconds(0))!=std::future_status::ready;
  model.cancelled.store(true);const auto result=task.get();
  const auto elapsed=std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-begin).count();
  const bool cancelled=pendingAtCancel&&!result.first&&result.second.find("cancelled")!=std::string::npos;
  std::cout << "{\"case\":\"active-cancellation\",\"accepted\":" << (cancelled?"true":"false") << ",\"pendingAtCancel\":" << (pendingAtCancel?"true":"false") << ",\"publishedText\":" << (result.first?"true":"false") << ",\"elapsedMs\":" << elapsed << ",\"error\":" << quote(result.second) << "}" << std::endl;
  if(!cancelled) ++failures;
  model.cancelled.store(false);
  const auto recovered=model.translate(instruction+"The meeting starts at nine.");
  const bool recovery=!recovered.empty()&&recovered.find("الاجتماع")!=std::string::npos;
  std::cout << "{\"case\":\"post-cancel-recovery\",\"accepted\":" << (recovery?"true":"false") << ",\"text\":" << quote(recovered) << "}" << std::endl;
  if(!recovery)++failures;
  return failures?1:0;
 } catch(const std::exception& e) { std::cerr << e.what() << std::endl;return 1; }
}
